import ClassMod, { ClassModData, defaultClassModInfo } from './ClassMod'
import { classModInfoIndex } from './info'
// Generated by mod_writer. `?url` makes Vite emit it as a separate, content-
// hashed file instead of bundling it, so app code and data are cached apart.
import classesUrl from './data/classes.json?url'

// Filled by loadClassModIndex() before the app renders
export const ClassModIndex: Map<string, ClassMod> = new Map()

export function classModIndex(): Map<string, ClassMod> {
    return ClassModIndex
}

export async function loadClassModIndex(): Promise<void> {
    const response = await fetch(classesUrl)
    if (!response.ok) {
        throw new Error(`Failed to load class data (HTTP ${response.status})`)
    }
    const classes: ClassModData[] = await response.json()
    const infoIndex = classModInfoIndex()

    ClassModIndex.clear()
    for (const data of classes) {
        const key = `Class_${data.key}`
        const info = infoIndex.get(key) ?? defaultClassModInfo()
        ClassModIndex.set(key, {
            data,
            info,
            synergies: info.synergy ?? new Set(data.synergies)
        })
    }
}
